// Earbud endurance index — record JAH-GPC-TWSEARBUDS-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"battery_h": 32, "anc_db": 28, "price_usd": 250};
var value = (m.battery_h*m.anc_db/m.price_usd*10);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GPC-TWSEARBUDS-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GPC-TWSEARBUDS-000001|' + value.toFixed(2) + ' endurance index');

